import numpy as np
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares

def tf(xyz=(0,0,0),rpy=(0,0,0)):
 t=np.eye(4); t[:3,:3]=R.from_euler('xyz',rpy).as_matrix();t[:3,3]=xyz;return t
origins=[tf((0,0,.333)),tf(rpy=(-np.pi/2,0,0)),tf((0,-.316,0),(np.pi/2,0,0)),tf((.0825,0,0),(np.pi/2,0,0)),tf((-.0825,.384,0),(-np.pi/2,0,0)),tf(rpy=(np.pi/2,0,0)),tf((.088,0,0),(np.pi/2,0,0))]
def fk(q,offset=.107):
 t=tf((0,-.4,.78),(0,0,np.pi/2))
 for o,a in zip(origins,q):t=t@o@tf(rpy=(0,0,a))
 return t@tf((0,0,offset),(0,0,-np.pi/4))
if __name__=='__main__':
 import json
 p=np.array(json.load(open('/app/output/initial/meta.json'))['proprio']['now'])
 for offset in [.107,.21,0]:
  t=fk(p[:7],offset);print(offset,t[:3,3],R.from_matrix(t[:3,:3]).as_quat(scalar_first=True))
